      }
    } else if (line.charAt(line.length - 1) === 'A') {
      doesNotStartWithBEndsWithA++;
    }
  });

  const largerCount = Math.max(
    startsWithBEndsWithoutA,
    doesNotStartWithBEndsWithA
  );
  const smallerCount = Math.min(
    startsWithBEndsWithoutA,
    doesNotStartWithBEndsWithA
  );
  const difference = smallerCount - largerCount;

  let adjustment = Math.max(
    0,
    startsWithBEndsWithA - difference
  );

