    if (value < 10) return 1;
    if (value < 100) return 2;
    if (value < 1000) return 3;
    if (value < 10000) return 4;
    if (value < 100000) return 5;
    if (value < 1000000) return 6;
    if (value < 10000000) return 7;
    return 8;
}

function powmod(base, exponent, modulus) {
    const chunkSize = 10000;
    let result = 1;

    while (exponent) {
        if (exponent & 1) {
            result =
                ((Math.floor(base / chunkSize) * result % modulus) * chunkSize +
                    (base % chunkSize) * result) %
                modulus;
        }

        base =
            ((Math.floor(base / chunkSize) * base % modulus) * chunkSize +
                (base % chunkSize) * base) %
            modulus;

        exponent >>>= 1;
    }

    return result;
}

